def number_to_turkish(n: int) -> str:
    """ Write the integer n (0 <= n <= 999) in Turkish words, separated by single spaces.
    Note that 100 is 'yüz' (not 'bir yüz').
    >>> number_to_turkish(0)
    'sıfır'
    >>> number_to_turkish(145)
    'yüz kırk beş'
    """
    if n == 0:
        return "sıfır"
    elif n == 100:
        return "yüz"
    elif n < 10:
        return "bir" + ("" if n == 1 else "i")
    elif n < 20:
        return "on" + ("" if n == 10 else "i")
    elif n < 100:
        return number_to_turkish(n // 10) + " " + ("yüz" if n % 10 == 0 else "yüz " + number_to_turkish(n % 10))
    else:
        return "yüz" + " yüz" + " yüz" + number_to_turkish(n % 100)
