def longest_balanced_prefix(s: str) -> int:
    balance = 0
    max_length = 0
    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            balance = 0
        max_length = max(max_length, balance)
    return max_length
